package com.android.messaging.sms;import android.app.Service;import android.content.Intent;import android.net.Uri;import android.os.IBinder;
public final class RespondViaMessageService extends Service{@Override public int onStartCommand(Intent i,int flags,int id){if(i!=null&&"android.intent.action.RESPOND_VIA_MESSAGE".equals(i.getAction())){Uri u=i.getData();String a=u==null?null:u.getSchemeSpecificPart(),t=i.getStringExtra(Intent.EXTRA_TEXT);if(a!=null){int q=a.indexOf('?');if(q>=0)a=a.substring(0,q);}final String aa=a,tt=t;new Thread(()->{try{if(aa!=null&&tt!=null&&!tt.trim().isEmpty())SmsSender.send(this,aa,tt);}catch(Exception ignored){}stopSelf(id);}).start();}else stopSelf(id);return START_NOT_STICKY;}@Override public IBinder onBind(Intent i){return null;}}
